// uuidPtrToStr converts *uuid.UUID to *string for DTOs.
func uuidPtrToStr(u *uuid.UUID) *string {
	if u == nil || *u == uuid.Nil {
		return nil
	}
	s := u.String()
	return &s
}

// mapErr converts domain errors to GraphQL-friendly errors.
func mapErr(err error) error {
	var de *domainErr.DomainError
	if errors.As(err, &de) {
		return de // already has code + message (unwraps fmt.Errorf wrappers)
	}
	if de := mapPostgresToDomain(err); de != nil {
		return de
	}
	// #region agent log
	if err != nil && strings.Contains(strings.ToLower(err.Error()), "organization") {
		agentDebugLog6008d1("H_unmapped_org_err", "resolver/mapErr", "organization-related error not mapped to DomainError", map[string]any{
			"errSnippet": truncateRunes(err.Error(), 480),
		})
	}
	// #endregion
	return err
}

const agentDebugLogPath6008d1 = "/Users/srhnergul/Desktop/masaustu/masterfabric-expo-base/.cursor/debug-6008d1.log"

// #region agent log
func agentDebugLog6008d1(hypothesisID, location, message string, data map[string]any) {
	type line struct {
		SessionID    string         `json:"sessionId"`
		HypothesisID string         `json:"hypothesisId"`
		Location     string         `json:"location"`
		Message      string         `json:"message"`
		Data         map[string]any `json:"data,omitempty"`
		Timestamp    int64          `json:"timestamp"`
	}
	b, mErr := json.Marshal(line{
		SessionID:    "6008d1",
		HypothesisID: hypothesisID,
		Location:     location,
		Message:      message,
		Data:         data,
		Timestamp:    time.Now().UnixMilli(),
	})
	if mErr != nil {
		return
	}
	f, oErr := os.OpenFile(agentDebugLogPath6008d1, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0600)
	if oErr != nil {
		return
	}
	_, _ = f.Write(append(b, '\n'))
	_ = f.Close()
}

func truncateRunes(s string, max int) string {
	if max <= 0 || len(s) <= max {
		return s
	}
	return s[:max] + "…"
}

// #endregion

// errorChainText joins Error() from err and each Unwrap for substring heuristics
// (some drivers wrap *pgconn.PgError so errors.As alone misses SQLSTATE in edge cases).
func errorChainText(err error) string {
	if err == nil {
		return ""
	}
	var b strings.Builder
	b.WriteString(err.Error())
	for e := errors.Unwrap(err); e != nil; e = errors.Unwrap(e) {
		b.WriteString(" | ")
		b.WriteString(e.Error())
	}
	return b.String()
}

// mapPostgresToDomain turns PostgreSQL failures into DomainErrors so clients
// see a clear code/message instead of a generic INTERNAL_ERROR (still logged server-side).
func mapPostgresToDomain(err error) *domainErr.DomainError {
	chain := errorChainText(err)
	lower := strings.ToLower(chain)

	// String fallbacks first — work even when *pgconn.PgError is not visible to errors.As.
	if strings.Contains(chain, "42703") || strings.Contains(lower, "undefined_column") {
		return domainErr.New(
			"SCHEMA_OUT_OF_DATE",
			"Database schema is missing a required column. Run mf-go migrations (e.g. 021_user_todos_due_at for user todos due time, 022 for org project todos).",
			err,
		)
	}
	if strings.Contains(lower, "42p01") || strings.Contains(lower, "undefined_table") {
		return domainErr.New(
			"SCHEMA_OUT_OF_DATE",
			"Database is missing required tables. Run mf-go migrations on the server (e.g. 019_organization_projects).",
			err,
		)
	}

	var pe *pgconn.PgError
	if errors.As(err, &pe) {
		// #region agent log
		agentDebugLog6008d1("H_pg_err", "resolver/mapPostgresToDomain", "wrapped pgconn.PgError", map[string]any{
			"sqlState": pe.Code,
			"table":    pe.TableName,
			"msgLen":   len(pe.Message),
		})
		// #endregion
		switch pe.Code {
		case "42P01": // undefined_table
			return domainErr.New(
				"SCHEMA_OUT_OF_DATE",
				"Database is missing required tables. Run mf-go migrations on the server (e.g. 019_organization_projects).",
				err,
			)
		case "42703": // undefined_column
			return domainErr.New(
				"SCHEMA_OUT_OF_DATE",
				"Database schema is missing a required column. Run mf-go migrations (e.g. 020_organization_project_todo_assignee for project todo assignee).",
				err,
			)
		case "23503": // foreign_key_violation
			return domainErr.New(
				"VALIDATION_ERROR",
				"Referenced user or relation is invalid for this operation.",
				err,
			)
		default:
			return domainErr.New(
				"DATABASE_ERROR",
				fmt.Sprintf("The database rejected this operation (SQLSTATE %s). Ensure migrations are applied and check server logs.", pe.Code),
				err,
			)
		}
	}
	if strings.Contains(lower, "due_at") &&
		(strings.Contains(lower, "does not exist") || strings.Contains(lower, "column")) {
		return domainErr.New(
			"SCHEMA_OUT_OF_DATE",
			"Database schema is missing due_at on todos. Run migrations 021_user_todos_due_at and 022_organization_project_todos_due_at.",
			err,
		)
	}
	if strings.Contains(lower, "assigned_to_user_id") &&
		(strings.Contains(lower, "does not exist") || strings.Contains(lower, "column")) {
		return domainErr.New(
			"SCHEMA_OUT_OF_DATE",
			"Database schema is missing assigned_to_user_id on organization project todos. Run migration 020_organization_project_todo_assignee.",
			err,
		)
	}
	if strings.Contains(lower, "organization_projects") &&
		(strings.Contains(lower, "does not exist") || strings.Contains(lower, "unknown relation")) {
		// #region agent log
		agentDebugLog6008d1("H_schema_string_match", "resolver/mapPostgresToDomain", "heuristic missing table", map[string]any{})
		// #endregion
		return domainErr.New(
			"SCHEMA_OUT_OF_DATE",
			"Database is missing required tables. Run mf-go migrations on the server (e.g. 019_organization_projects).",
			err,
		)
	}
	return nil
}

