// todoRespToModel converts a todo DTO to the GraphQL UserTodo model.
func todoRespToModel(resp *todosDTO.TodoResponse) *model.UserTodo {
	id, _ := uuid.Parse(resp.ID)
	userID, _ := uuid.Parse(resp.UserID)
	createdAt, _ := time.Parse(time.RFC3339, resp.CreatedAt)
	updatedAt, _ := time.Parse(time.RFC3339, resp.UpdatedAt)
	out := &model.UserTodo{
		ID:        id,
		UserID:    userID,
		Title:     resp.Title,
		Completed: resp.Completed,
		CreatedAt: createdAt,
		UpdatedAt: updatedAt,
	}
	if resp.OrganizationID != nil {
		parsed, _ := uuid.Parse(*resp.OrganizationID)
		out.OrganizationID = &parsed
	}
	if resp.AssignedToUserID != nil {
		parsed, _ := uuid.Parse(*resp.AssignedToUserID)
		out.AssignedToUserID = &parsed
	}
	if resp.DueAt != nil {
		dueAt, _ := time.Parse(time.RFC3339, *resp.DueAt)
		out.DueAt = &dueAt
	}
	return out
}

