// orgMemberRespToModel converts an organization member DTO to the GraphQL OrganizationMember model.
func orgMemberRespToModel(resp *organizationDTO.OrganizationMemberResponse) *model.OrganizationMember {
	id, _ := uuid.Parse(resp.ID)
	orgID, _ := uuid.Parse(resp.OrganizationID)
	userID, _ := uuid.Parse(resp.UserID)
	joinedAt, _ := time.Parse(time.RFC3339, resp.JoinedAt)
	nickname := resp.UserNickname
	if nickname == "" && len(resp.UserID) >= 8 {
		nickname = resp.UserID[:8] + "…" // fallback when user has no nickname
	}
	if nickname == "" {
		nickname = "—"
	}
	return &model.OrganizationMember{
		ID:               id,
		OrganizationID:   orgID,
		UserID:           userID,
		UserNickname:     nickname,
		Role:             orgMemberRoleToModel(resp.Role),
		MembershipStatus: orgMembershipStatusToModel(resp.MembershipStatus),
		JoinedAt:         joinedAt,
	}
}

