func feedbackAuthorRole(s string) model.FeedbackAuthorRole {
	switch s {
	case "ADMIN":
		return model.FeedbackAuthorRoleAdmin
	default:
		return model.FeedbackAuthorRoleUser
	}
}

func feedbackMessageDTOToModel(m *feedbackDTO.FeedbackMessageResponse) *model.FeedbackMessage {
	id, _ := uuid.Parse(m.ID)
	tid, _ := uuid.Parse(m.ThreadID)
	return &model.FeedbackMessage{
		ID:         id,
		ThreadID:   tid,
		AuthorRole: feedbackAuthorRole(m.AuthorRole),
		Body:       m.Body,
		CreatedAt:  m.CreatedAt,
	}
}

func feedbackThreadDTOToModel(resp *feedbackDTO.FeedbackThreadResponse) *model.FeedbackThread {
	id, _ := uuid.Parse(resp.ID)
	var userID *uuid.UUID
	if resp.UserID != "" {
		if u, err := uuid.Parse(resp.UserID); err == nil {
			userID = &u
		}
	}
	msgs := make([]*model.FeedbackMessage, 0, len(resp.Messages))
	for _, m := range resp.Messages {
		if m != nil {
			msgs = append(msgs, feedbackMessageDTOToModel(m))
		}
	}
	return &model.FeedbackThread{
		ID:           id,
		UserID:       userID,
		ContactEmail: resp.ContactEmail,
		Subject:      resp.Subject,
		Status:       resp.Status,
		CreatedAt:    resp.CreatedAt,
		UpdatedAt:    resp.UpdatedAt,
		Messages:     msgs,
	}
}

// ── OTP helpers ─────────────────────────────────────────────────────────────

func gqlOTPPurposeToString(p model.OTPPurpose) string {
	switch p {
	case model.OTPPurposeLogin:
		return "login"
	case model.OTPPurposeVerifyIDEntity:
		return "verify_identity"
	case model.OTPPurposePasswordReset:
		return "password_reset"
	case model.OTPPurposeAccountActivate:
		return "account_activate"
	case model.OTPPurposeEmailChange:
		return "email_change"
	default:
		return "login"
	}
}

func gqlOTPChannel(ch string) model.OTPChannel {
	switch ch {
	case "admin_panel":
		return model.OTPChannelAdminPanel
	case "email":
		return model.OTPChannelEmail
	case "sms":
		return model.OTPChannelSms
	case "whatsapp":
		return model.OTPChannelWhatsapp
	case "telegram":
		return model.OTPChannelTelegram
	default:
		return model.OTPChannelAdminPanel
	}
}

func gqlOTPPurpose(p string) model.OTPPurpose {
	switch p {
	case "login":
		return model.OTPPurposeLogin
	case "verify_identity":
		return model.OTPPurposeVerifyIDEntity
	case "password_reset":
		return model.OTPPurposePasswordReset
	case "account_activate":
		return model.OTPPurposeAccountActivate
	case "email_change":
		return model.OTPPurposeEmailChange
	default:
		return model.OTPPurposeLogin
	}
}

func gqlOTPStatus(s string) model.OTPStatus {
	switch s {
	case "pending":
		return model.OTPStatusPending
	case "verified":
		return model.OTPStatusVerified
	case "expired":
		return model.OTPStatusExpired
	default:
		return model.OTPStatusPending
	}
}

func adminOTPsToModel(otps []*otpDTO.AdminOTPResponse) []*model.AdminOTPEntry {
	result := make([]*model.AdminOTPEntry, 0, len(otps))
	for _, o := range otps {
		id, _ := uuid.Parse(o.ID)
		uid, _ := uuid.Parse(o.UserID)
		result = append(result, &model.AdminOTPEntry{
			ID:         id,
			UserID:     uid,
			Code:       o.Code,
			Channel:    gqlOTPChannel(o.Channel),
			Purpose:    gqlOTPPurpose(o.Purpose),
			Status:     gqlOTPStatus(o.Status),
			Attempts:   o.Attempts,
			MaxRetries: o.MaxRetries,
			ExpiresAt:  o.ExpiresAt,
			VerifiedAt: o.VerifiedAt,
			CreatedAt:  o.CreatedAt,
		})
	}
	return result
}
